python - <<'PY'
import json,numpy as np
from PIL import Image
m=json.load(open('/app/runs/rotated_current/meta.json'));c=m['cameras']['robot0_agentview_right'];T=np.array(c['cam2world_gl']);K=np.array(c['intrinsic_cv']);d=np.load('/app/runs/rotated_current/depth_robot0_agentview_right.npy')[0];im=np.array(Image.open('/app/runs/rotated_current/last/robot0_agentview_right.jpg')); H,W=d.shape
pts=[];pix=[]
for v in range(130,180):
 for u in range(125,180):
  R,G,B=im[v,u].astype(float);z=float(d[v,u])
  if z==0 or not (R>60 and R>G*1.4 and R>B*1.2 and G<100 and B<100): continue
  ray=np.array([(u-160)/K[0,0],-(v-120)/K[1,1],-1]);p=T[:3,3]+T[:3,:3]@(ray*z)
  if .94<p[2]<1.10: pts.append(p);pix.append((u,v,R,G,B,z))
pts=np.array(pts);print('count',len(pts))
if len(pts):
 print('ranges x y z',np.percentile(pts,[0,10,25,50,75,90,100],axis=0));
 for i in range(0,len(pts),max(1,len(pts)//40)): print(pix[i],np.round(pts[i],3))
PY
